  for (const issue of tree) {
    if (issue.parentId === null) continue;
    const siblings = children.get(issue.parentId) ?? [];
    siblings.push(issue);
    children.set(issue.parentId, siblings);
  }
  const result: { issue: Issue; depth: number }[] = [];
  const seen = new Set<IssueId>([issueId]);
  const queue = [{ id: issueId, depth: 0 }];
  for (let i = 0; i < queue.length; i++) {
    const entry = queue[i];
    for (const issue of children.get(entry.id) ?? []) {
      if (seen.has(issue.id)) continue;
      seen.add(issue.id);
      const depth = entry.depth + 1;
      result.push({ issue, depth });
      queue.push({ id: issue.id, depth });
    }
  }
  return result;
}

async function validateParent(
  orgId: OrgId, projectId: ProjectId, parentId: IssueId, issueId: IssueId, height: number,
): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  requireFound(parent?.projectId === projectId ? parent : null, \"Issue\", parentId);
  assertNotArchived(\"Issue\", parentId, parent"'!);
  const seen = new Set<IssueId>();
  let current: Issue | null = parent;
  let level = 1;
  while (current !== null) {
    if (current.id === issueId && issueId !== parentId || seen.has(current.id)) {
      throw new IssueHierarchyError(issueId, "cycle");
    }
    seen.add(current.id);
    if (current.parentId === null) break;
    current = await issueRepo.findIssueById(orgId, current.parentId);
    level++;
  }
  if (level + height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}

export async function setIssueParent(actor: Actor, input: SetIssueParentInput): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  const issue = requireFound(await issueRepo.findIssueById(input.orgId, input.issueId), "Issue", input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  const tree = await issueRepo.listProjectHierarchy(input.orgId, issue.projectId);
  const below = descendants(tree, issue.id);
  if (input.parentId !== null) {
    if (input.parentId === issue.id || below.some(entry => entry.issue.id === input.parentId)) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    await validateParent(input.orgId, issue.projectId, input.parentId, issue.id,
      below.reduce((height, entry) => Math.max(height, entry.depth), 0));
  }
  if (issue.parentId === input.parentId) return issue;
  const after = await issueRepo.setIssueParent(input.orgId, issue.id, input.parentId);
  await emit("issue.updated", {
    ...actorEnvelope(actor), issueId: after.id, projectId: after.projectId, changedFields: ["parentId"],
  });
  return after;
}

async function readableIssue(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<Issue> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  return issue;
}

export async function listSubIssues(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<readonly Issue[]> {
  const issue = await readableIssue(actor, orgId, issueId);
  const tree = await issueRepo.listProjectHierarchy(orgId, issue.projectId);
  return tree.filter(item => item.parentId === issueId && item.archivedAt === null)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.number - b.number);
}

function rollup(tree: readonly Issue[], issueId: IssueId): IssueRollup {
  const live = descendants(tree, issueId).filter(entry => entry.issue.archivedAt === null);
  const closed = live.filter(entry => CLOSED_ISSUE_STATUSES.includes(entry.issue.status)).length;
  return { total: live.length, open: live.length - closed, closed };
}

export async function getIssueRollup(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<IssueRollup> {
  const issue = await readableIssue(actor, orgId, issueId);
  return rollup(await issueRepo.listProjectHierarchy(orgId, issue.projectId), issueId);
}

async function notifyCompletedParents(actor: Actor, closing: readonly Issue[]): Promise<void> {
  const parentIds = new Set(closing.flatMap(issue => issue.parentId === null ? [] : [issue.parentId]));
  for (const parentId of parentIds) {
    const parent = await issueRepo.findIssueById(actor.orgId, parentId);
    if (!parent || parent.archivedAt !== null || parent.assigneeId === null) continue;
    const tree = await issueRepo.listProjectHierarchy(actor.orgId, parent.projectId);
    if (rollup(tree, parent.id).open !== 0) continue;
    await notify(actor.orgId, "sub_issues_completed", [parent.assigneeId], {
      title: "All sub-issues completed",
      body: `All sub-issues of ${parent.title} are closed`,
      href: `/issues/${parent.id}`,
      actorId: actor.userId,
    });
  }
}
