describe("issue hierarchies", () => {
  it("moves a subtree, removes its parent, and announces only parentId", async () => {
    const root = await create();
    const child = await create(root.id);
    const grandchild = await create(child.id);
    const destination = await create();
    const events: unknown[] = [];
    const off = subscribe("issue.updated", event => { events.push(event); });
    try {
      expect((await setParent(child.id, destination.id)).parentId).toBe(destination.id);
      expect(await rollup(root.id)).toEqual({ total: 0, open: 0, closed: 0 });
      expect(await rollup(destination.id)).toEqual({ total: 2, open: 2, closed: 0 });
      expect((await issueRepo.findIssueById(tenant.org.id, grandchild.id))?.parentId).toBe(child.id);
      expect((await setParent(child.id, null)).parentId).toBeNull();
      expect(events).toHaveLength(2);
      expect(events[0]).toMatchObject({ issueId: child.id, changedFields: ["parentId"] });
    } finally { off(); }
  });

  it("refuses cycles and moves whose deepest descendant would exceed level three", async () => {
    const root = await create();
    const one = await create(root.id);
    const two = await create(one.id);
    const three = await create(two.id);
    const branch = await create();
    await create(branch.id);
    await expect(setParent(root.id, three.id)).rejects.toMatchObject({ reason: "cycle" });
    await expect(setParent(one.id, one.id)).rejects.toMatchObject({ reason: "cycle" });
    await expect(setParent(branch.id, two.id)).rejects.toMatchObject({ reason: "too_deep" });
    expect((await issueRepo.findIssueById(tenant.org.id, branch.id))?.parentId).toBeNull();
    const count = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    const events: unknown[] = [];
    const off = subscribe("issue.created", event => { events.push(event); });
    try {
      await expect(create(three.id)).rejects.toBeInstanceOf(IssueHierarchyError);
      expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(count);
      expect(events).toHaveLength(0);
    } finally { off(); }
    const error = new IssueHierarchyError(branch.id, "too_deep");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error)).toMatchObject({ code: "conflict", meta: { reason: "too_deep" } });
  });

  it("enforces workspace, lookup, permission and archived guards", async () => {
