      () => issues.listSubIssues(other.actors.owner, tenant.org.id, root.id),
      () => issues.getIssueRollup(other.actors.owner, tenant.org.id, root.id),
    ]) await expect(operation()).rejects.toBeInstanceOf(TenantScopeError);
    await expect(setParent(foreign.id, null)).rejects.toBeInstanceOf(NotFoundError);
    await expect(setParent(root.id, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(create(foreign.id)).rejects.toBeInstanceOf(NotFoundError);
