    });
    const another = await issues.createIssue(tenant.actors.member, issueInput(tenant.org.id, project.id));
    await expect(setParent(root.id, another.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(create(another.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(issues.setIssueParent(tenant.actors.viewer, {
      orgId: tenant.org.id, issueId: root.id, parentId: null,
    })).rejects.toBeInstanceOf(PermissionDeniedError);
    await issues.archiveIssue(tenant.actors.member, tenant.org.id, root.id);
    await expect(setParent(root.id, null)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(create(root.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    const live = await create();
    await expect(setParent(live.id, root.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("lists direct live children oldest first and counts all live descendants without pagination", async () => {
    const root = await create();
    const first = await create(root.id, "done");
    const second = await create(root.id, "canceled");
