      expect(archivedIds.sort()).toEqual([child.id, grandchild.id].sort());
      expect(await issueRepo.findIssueById(tenant.org.id, already.id)).toEqual(previous);
      expect((await issueRepo.findIssueById(tenant.org.id, root.id))?.archivedAt).toBeNull();
    } finally { off(); }
  });

  it("notifies only on the last closing, and again after a reopen", async () => {
    const parent = await assignedParent();
