    const nested = await create(first.id);
    await status(first.id, "done");
    await status(second.id, "canceled");
    expect(await notices(parent.id)).toHaveLength(0);
    // Closing the nested child considers only its direct parent.
    await status(nested.id, "done");
    expect(await notices(parent.id)).toHaveLength(0);
    await status(second.id, "todo");
    await status(second.id, "done");
    expect(await notices(parent.id)).toHaveLength(1);
    await status(second.id, "canceled");
    await status(second.id, "canceled");
    expect(await notices(parent.id)).toHaveLength(1);
    await status(second.id, "in_progress");
    await status(second.id, "done");
    expect(await notices(parent.id)).toHaveLength(2);
  });

  it("notifies for archiving the last open child and honors preferences and self suppression", async () => {
    const parent = await assignedParent();
    const child = await create(parent.id);
    await issues.archiveIssue(tenant.actors.member, tenant.org.id, child.id);
